import{_ as t,o as e,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const g=JSON.parse('{"title":"Agent、Workflow 与多 Agent 架构","description":"比较普通函数、固定工作流、单 Agent、Agentic Workflow 与多 Agent 的控制结构、适用约束和演进路径。","frontmatter":{"title":"Agent、Workflow 与多 Agent 架构","description":"比较普通函数、固定工作流、单 Agent、Agentic Workflow 与多 Agent 的控制结构、适用约束和演进路径。","verified_at":"2026-07-31","source":["https://docs.langchain.com/oss/python/langgraph/workflows-agents","https://docs.langchain.com/oss/python/langchain/multi-agent","https://www.anthropic.com/research/building-effective-agents"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/architecture/system-architecture/agent-workflow-multi-agent-architecture.md","filePath":"py-agent/architecture/system-architecture/agent-workflow-multi-agent-architecture.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/system-architecture/agent-workflow-multi-agent-architecture.md"};function s(i,a,o,d,p,c){return e(),n("div",null,[...a[0]||(a[0]=[r(`<h1 id="agent、workflow-与多-agent-架构" tabindex="-1">Agent、Workflow 与多 Agent 架构 <a class="header-anchor" href="#agent、workflow-与多-agent-架构" aria-label="Permalink to &quot;Agent、Workflow 与多 Agent 架构&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Agent、Workflow 和多 Agent 不是成熟度阶梯。它们代表不同控制权分配：代码是否预先决定步骤，模型是否选择动作，多个模型角色是否需要协议协调。更动态的结构增加适应性，也增加不确定性、成本和验证难度。</p><p>本章只负责架构选择。状态图的组成和执行语义见<a href="/py-agent/workflow/workflow-foundations/workflow-modeling-boundaries">工作流建模与边界</a>，协作模式与协调成本见<a href="/py-agent/workflow/multi-agent-patterns/multi-agent-boundaries-costs">多 Agent 边界与成本</a>。</p><h2 id="_1-决策问题" tabindex="-1">1. 决策问题 <a class="header-anchor" href="#_1-决策问题" aria-label="Permalink to &quot;1. 决策问题&quot;">​</a></h2><p>需要先回答：任务步骤是否已知、分支是否有限、是否需要在运行时选择工具、状态是否要持久恢复、多个角色是否拥有不同上下文或权限，以及失败损失多大。</p><p>核心原则是使用满足需求的最简单控制结构。能用确定函数完成的计算，不需要模型；能用固定图表达的流程，不需要自由循环；单 Agent 能解决时，不要引入协调网络。</p><h2 id="_2-五种控制结构" tabindex="-1">2. 五种控制结构 <a class="header-anchor" href="#_2-五种控制结构" aria-label="Permalink to &quot;2. 五种控制结构&quot;">​</a></h2><h3 id="_2-1-普通函数与服务编排" tabindex="-1">2.1 普通函数与服务编排 <a class="header-anchor" href="#_2-1-普通函数与服务编排" aria-label="Permalink to &quot;2.1 普通函数与服务编排&quot;">​</a></h3><p>步骤和规则完全由代码决定，输入输出可精确验证。适合校验、计算、数据转换、权限和明确业务状态机。模型可以作为一个受控函数被调用。</p><h3 id="_2-2-固定-workflow" tabindex="-1">2.2 固定 Workflow <a class="header-anchor" href="#_2-2-固定-workflow" aria-label="Permalink to &quot;2.2 固定 Workflow&quot;">​</a></h3><p>节点与边预先定义，允许条件、并行、重试、人工中断和恢复。适合审批、内容流水线、ETL 和高可控业务流程。</p><h3 id="_2-3-单-agent" tabindex="-1">2.3 单 Agent <a class="header-anchor" href="#_2-3-单-agent" aria-label="Permalink to &quot;2.3 单 Agent&quot;">​</a></h3><p>模型在允许工具与预算内选择下一动作，适合路径难以穷举但目标清楚的任务，如开放检索或动态问题排查。</p><h3 id="_2-4-agentic-workflow" tabindex="-1">2.4 Agentic Workflow <a class="header-anchor" href="#_2-4-agentic-workflow" aria-label="Permalink to &quot;2.4 Agentic Workflow&quot;">​</a></h3><p>外层图固定关键阶段与控制点，局部节点允许 Agent 自主决策。它常是生产系统的实用折中：确定性骨架限制风险，Agent 处理开放子任务。</p><h3 id="_2-5-多-agent" tabindex="-1">2.5 多 Agent <a class="header-anchor" href="#_2-5-多-agent" aria-label="Permalink to &quot;2.5 多 Agent&quot;">​</a></h3><p>多个 Agent 具有独立角色、上下文、工具或所有权，并通过 Router、Handoff、Supervisor 等协议协作。适合上下文隔离、权限隔离或可并行专业任务，不适合仅为了“模拟团队”。</p><h2 id="_3-比较维度" tabindex="-1">3. 比较维度 <a class="header-anchor" href="#_3-比较维度" aria-label="Permalink to &quot;3. 比较维度&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>函数</th><th>Workflow</th><th>单 Agent</th><th>Agentic Workflow</th><th>多 Agent</th></tr></thead><tbody><tr><td>控制路径</td><td>固定</td><td>显式图</td><td>模型决定</td><td>图 + 局部模型</td><td>协议 + 多模型</td></tr><tr><td>可预测性</td><td>最高</td><td>高</td><td>中低</td><td>中高</td><td>最低</td></tr><tr><td>开放任务</td><td>弱</td><td>中</td><td>强</td><td>强</td><td>强</td></tr><tr><td>恢复</td><td>代码实现</td><td>Checkpoint</td><td>需运行时支持</td><td>强</td><td>跨 Agent 更复杂</td></tr><tr><td>权限隔离</td><td>明确</td><td>按节点</td><td>易过度授权</td><td>可按节点</td><td>可按角色</td></tr><tr><td>成本/延迟</td><td>最低</td><td>低中</td><td>中高</td><td>中高</td><td>最高</td></tr><tr><td>评测难度</td><td>低</td><td>路径/状态</td><td>轨迹/结果</td><td>二者结合</td><td>再加协作质量</td></tr></tbody></table><p>表格表达相对趋势，不是对每个实现的保证。</p><h3 id="_3-1-快速决策树" tabindex="-1">3.1 快速决策树 <a class="header-anchor" href="#_3-1-快速决策树" aria-label="Permalink to &quot;3.1 快速决策树&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务是否短、局部、无持久等待，而且步骤能由确定规则完整表达？</span></span>
<span class="line"><span>  是 -&gt; 单个函数或普通服务编排</span></span>
<span class="line"><span>  否 -&gt; 阶段、分支和终态是否大体可枚举？</span></span>
<span class="line"><span>         是 -&gt; 固定 Workflow</span></span>
<span class="line"><span>               某个局部步骤是否必须根据中间观察动态选择动作？</span></span>
<span class="line"><span>                 否 -&gt; 保持固定 Workflow</span></span>
<span class="line"><span>                 是 -&gt; Agentic Workflow：只让该节点使用 Agent</span></span>
<span class="line"><span>         否 -&gt; 单 Agent 是否能在同一上下文、权限和预算内完成？</span></span>
<span class="line"><span>                是 -&gt; 单 Agent</span></span>
<span class="line"><span>                否 -&gt; 是否存在独立权限、上下文、并行所有权或远程服务边界？</span></span>
<span class="line"><span>                       是 -&gt; 多 Agent</span></span>
<span class="line"><span>                       否 -&gt; 重新缩小任务或改进单 Agent，不因角色名称拆分</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>任何分支都可以回退到更简单结构。决策树只缩小候选，最终还要用同一任务集比较质量、风险、延迟和每成功任务成本。</p><h2 id="_4-选择固定-workflow" tabindex="-1">4. 选择固定 Workflow <a class="header-anchor" href="#_4-选择固定-workflow" aria-label="Permalink to &quot;4. 选择固定 Workflow&quot;">​</a></h2><p>以下特征偏向 Workflow：</p><ul><li>法规或业务步骤必须按顺序；</li><li>每个分支和终态可枚举；</li><li>写副作用需要精确重试和补偿；</li><li>人工批准点固定；</li><li>运行必须跨小时或天恢复；</li><li>需要明确解释为什么走某条路径。</li></ul><p>模型可用于某个节点的分类或生成，但不拥有整个控制流。</p><h2 id="_5-选择单-agent" tabindex="-1">5. 选择单 Agent <a class="header-anchor" href="#_5-选择单-agent" aria-label="Permalink to &quot;5. 选择单 Agent&quot;">​</a></h2><p>以下特征偏向单 Agent：</p><ul><li>达成目标的步骤取决于中间观察；</li><li>工具数量有限且权限可约束；</li><li>错误可被检测、回退或由用户纠正；</li><li>任务有明确预算与停止条件；</li><li>数据集能评测工具选择和最终结果。</li></ul><p>单 Agent 并不意味着没有状态和中间件。生产运行仍需 Deadline、Checkpoint、授权、Trace 和质量门禁。</p><h2 id="_6-选择-agentic-workflow" tabindex="-1">6. 选择 Agentic Workflow <a class="header-anchor" href="#_6-选择-agentic-workflow" aria-label="Permalink to &quot;6. 选择 Agentic Workflow&quot;">​</a></h2><p>当流程既有确定阶段又含开放子任务时，采用外层图：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>validate -&gt; plan -&gt; research_agent -&gt; evidence_check</span></span>
<span class="line"><span>                              ^              |</span></span>
<span class="line"><span>                              | retry        v</span></span>
<span class="line"><span>                         human_review &lt;- synthesize</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>validate</code>、证据门槛和人工审核是确定节点；<code>research_agent</code> 可动态选择搜索工具。每个开放子任务都有自己的工具、步数和 Token 预算。</p><h2 id="_7-选择多-agent" tabindex="-1">7. 选择多 Agent <a class="header-anchor" href="#_7-选择多-agent" aria-label="Permalink to &quot;7. 选择多 Agent&quot;">​</a></h2><p>只有出现以下至少一种真实边界时再考虑：</p><ul><li>不同角色需要互斥工具或数据权限；</li><li>上下文过大，需要按领域隔离；</li><li>子任务可并行且结果可独立验证；</li><li>不同团队/服务拥有独立能力；</li><li>协作协议本身是产品需求。</li></ul><p>若只是给同一模型换几段角色提示，多个 Agent 可能只增加 Token 和错误传播。</p><h2 id="_8-状态与通信" tabindex="-1">8. 状态与通信 <a class="header-anchor" href="#_8-状态与通信" aria-label="Permalink to &quot;8. 状态与通信&quot;">​</a></h2><h3 id="_8-1-共享-state" tabindex="-1">8.1 共享 State <a class="header-anchor" href="#_8-1-共享-state" aria-label="Permalink to &quot;8.1 共享 State&quot;">​</a></h3><p>Workflow 共享结构化 State，节点只写自己拥有字段；Reducer 解决并行合并。自然语言消息不应承担全部状态职责。</p><h3 id="_8-2-agent-handoff" tabindex="-1">8.2 Agent Handoff <a class="header-anchor" href="#_8-2-agent-handoff" aria-label="Permalink to &quot;8.2 Agent Handoff&quot;">​</a></h3><p>传递结构化任务、允许范围、上下文引用、预期产物和截止时间，而不是倾倒完整对话。接收方验证协议和权限。</p><h3 id="_8-3-artifact" tabindex="-1">8.3 Artifact <a class="header-anchor" href="#_8-3-artifact" aria-label="Permalink to &quot;8.3 Artifact&quot;">​</a></h3><p>研究笔记、代码 Patch、SQL 计划等较大产物存于受控 Artifact Store，消息只传 ID、摘要、版本和校验值。</p><h3 id="_8-4-终止" tabindex="-1">8.4 终止 <a class="header-anchor" href="#_8-4-终止" aria-label="Permalink to &quot;8.4 终止&quot;">​</a></h3><p>定义成功、失败、预算耗尽、无进展、冲突和人工中止。多个 Agent 互相转交不是进展，需检测循环。</p><h2 id="_9-可靠性与副作用" tabindex="-1">9. 可靠性与副作用 <a class="header-anchor" href="#_9-可靠性与副作用" aria-label="Permalink to &quot;9. 可靠性与副作用&quot;">​</a></h2><p>确定节点可按异常类型重试；Agent 模型调用可重试但可能产生不同决策；写工具只在幂等或可确认后重试。Checkpoint 恢复执行位置，不能撤销已发生外部动作。</p><p>多 Agent 的失败域应隔离：一个 Worker 超时不必重启所有角色；Supervisor 也不能成为无限重试单点。预算按整次任务与角色双层限制。</p><p>Checkpoint、Interrupt 和恢复的实现边界见<a href="/py-agent/workflow/durable-execution-recovery/durable-execution-failure-recovery">Durable Execution 与故障恢复</a>；外部副作用仍需单独设计幂等与补偿。</p><h2 id="_10-演进路径" tabindex="-1">10. 演进路径 <a class="header-anchor" href="#_10-演进路径" aria-label="Permalink to &quot;10. 演进路径&quot;">​</a></h2><ol><li>用函数实现可确定部分；</li><li>多阶段需求出现时引入显式 Workflow；</li><li>对路径无法枚举的局部节点引入 Agent；</li><li>只有上下文、权限或并行所有权形成边界时拆多 Agent；</li><li>用 Trace 和评测证明新增动态性带来净收益。</li></ol><p>从多 Agent 回退到更简单结构同样是合理演进，不代表失败。</p><h2 id="_11-评测与决策记录" tabindex="-1">11. 评测与决策记录 <a class="header-anchor" href="#_11-评测与决策记录" aria-label="Permalink to &quot;11. 评测与决策记录&quot;">​</a></h2><p>比较候选时使用相同任务数据，报告成功率、路径合法率、工具错误、恢复、副作用、p95 延迟、Token、每成功任务成本和人工接管。多 Agent 还测 Handoff 正确率、重复工作和冲突率。</p><p>决策记录写明选择结构、被拒方案、驱动约束、自治边界、状态所有权、停止条件和复查触发器。</p><h2 id="_12-常见误区" tabindex="-1">12. 常见误区 <a class="header-anchor" href="#_12-常见误区" aria-label="Permalink to &quot;12. 常见误区&quot;">​</a></h2><ol><li><strong>多 Agent 一定更智能</strong>：协调误差和成本也会叠加。</li><li><strong>Workflow 没有 Agent 就不先进</strong>：确定流程往往更可靠。</li><li><strong>单 Agent 等于一个 Prompt</strong>：仍需状态、工具、边界和恢复。</li><li><strong>Checkpoint 能回滚外部动作</strong>：它只恢复内部执行状态。</li><li><strong>用演示成功代替比较实验</strong>：无法证明复杂架构值得。</li></ol><p>选择的本质是控制权：哪些步骤交给代码，哪些交给模型，哪些分配给独立角色。把控制权限制在真正需要适应性的区域，通常比把整个系统“Agent 化”更可靠。</p>`,62)])])}const u=t(l,[["render",s]]);export{g as __pageData,u as default};
